import { tags } from "typia";

/**
 * Daily completion record containing task completion count for a specific
 * calendar day.
 *
 * This structured data organizes daily task completion statistics
 * chronologically, enabling timeline analysis and productivity pattern
 * identification. Each entry represents a single day's completion activity and
 * contributes to overall trend analysis and productivity visualization.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDailyCompletionEntry = {
  /**
   * Calendar date representing the specific day for which completion
   * statistics are recorded.
   */
  date: string & tags.Format<"date">;

  /**
   * Number of task completion events that occurred on this specific date,
   * providing daily productivity volume measurement.
   */
  completion_count: number & tags.Type<"int32"> & tags.Minimum<0>;
};
